{"command":"python - <<'PY'
from more_itertools import chunked

assert list(chunked(range(5), 2)) == [[0, 1], [2, 3], [4]]
assert list(chunked(range(4), 2, strict=True)) == [[0, 1], [2, 3]]
assert list(chunked([], 3)) == []
try:
    list(chunked(range(5), 2, strict=True))
except ValueError as exc:
    assert str(exc) == 'iterable is not divisible by n.'
else:
    raise AssertionError('strict chunked must reject remainder')
try:
    list(chunked(range(5), None, strict=True))
except ValueError as exc:
    assert str(exc) == 'n must not be None when using strict mode.'
else:
    raise AssertionError('strict chunked must reject n=None')
print('chunked reproduction and edge cases passed')
PY"}

